template.xpath:
/* Native Papierformate werden bereits durch ir.actions.report/paperformat
   gedreht bzw. auf Sondermaß gesetzt. Deshalb hier KEINE zusätzliche
   CSS-Rotation. Der bisherige sab-master-landscape-Rotationstrick bleibt
   ausschließlich für den gemischten A4-Fertigungsordner bestehen. */
.sab-master-native-landscape {
    width: 277mm !important;
    min-width: 277mm !important;
    max-width: 277mm !important;
    height: 190mm !important;
    min-height: 190mm !important;
    max-height: 190mm !important;
    margin: 0 auto !important;
    position: relative !important;
    overflow: hidden !important;
    transform: none !important;
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}
.sab-master-native-landscape table,
.sab-master-native-landscape tr,
.sab-master-native-landscape td,
.sab-master-native-landscape th {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}
.sab-master-native-landscape .m-cell {
    padding: 0.25mm 0.65mm !important;
}

.sab-info-native-page {
    position: relative !important;
    width: 265mm !important;
    min-width: 265mm !important;
    max-width: 265mm !important;
    height: 176mm !important;
    min-height: 176mm !important;
    max-height: 176mm !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow: hidden !important;
}
.sab-info-native-card {
    position: relative !important;
    width: 265mm !important;
    height: 176mm !important;
    left: 0 !important;
    top: 0 !important;
    margin: 0 !important;
    transform: none !important;
    transform-origin: top left !important;
}
